function finishGame(){running=false;ui.ending.classList.remove('hidden')}
const CY=128;
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function draw(){ctx.clearRect(0,0,W,H);const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#07131d');sky.addColorStop(.58,'#10252d');sky.addColorStop(1,'#080f17');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant station ribs and cold lights
ctx.save();for(const s of stars){let sx=(s.x-cam*.16)%worldW;if(sx<0)sx+=worldW;sx%=W;ctx.fillStyle=`rgba(118,210,210,${s.a})`;ctx.fillRect(sx,s.y*.65,Math.max(1,s.r),Math.max(1,s.r))}for(let i=-1;i<8;i++){let x=i*180-(cam*.28%180);ctx.fillStyle='#10242d';ctx.fillRect(x,65,56,340);ctx.fillStyle='#19323a';ctx.fillRect(x+7,80,5,280);ctx.fillStyle='#0a1a22';ctx.fillRect(x+42,80,8,280);ctx.fillStyle='#27505a';ctx.fillRect(x+9,174,3,56);ctx.fillRect(x+9,285,3,42)}ctx.restore();
const sx=x=>Math.round(x-cam), sy=y=>Math.round(y-CY);
// parallax conduits
ctx.strokeStyle='#1b3d45';ctx.lineWidth=3;for(let i=-1;i<9;i++){let x=i*170-(cam*.55%170);ctx.beginPath();ctx.moveTo(x,sy(390));ctx.lineTo(x+70,sy(390));ctx.lineTo(x+70,sy(ground));ctx.stroke();ctx.fillStyle='#2d6870';ctx.fillRect(x+65,sy(ground)-8,10,3)}
// floors and platforms
for(const p of platforms){let x=sx(p.x),y=sy(p.y);ctx.fillStyle='#132a33';ctx.fillRect(x,y,p.w,p.h);ctx.fillStyle='#28505a';ctx.fillRect(x,y,p.w,5);ctx.fillStyle='#0b1b24';ctx.fillRect(x,y+8,p.w,p.h-8);for(let xx=x+12;xx<x+p.w;xx+=44){ctx.fillStyle='#1d3941';ctx.fillRect(xx,y+19,2,Math.min(50,p.h-20));ctx.fillStyle='#244750';ctx.fillRect(xx+6,y+20,12,2)}ctx.fillStyle='#60aaa6';ctx.fillRect(x,y,p.w,1)}
// area signage
const signs=[['INTAKE',150],['BIO-VAULT',1140],['REACTOR',2075],['LAUNCH BAY',3000]];for(const [name,x] of signs){let xx=sx(x);if(xx<-200||xx>W+50)continue;ctx.fillStyle='#a1c9c8';ctx.font='12px monospace';ctx.fillText(name,xx,sy(175));ctx.fillStyle='#31545a';ctx.fillRect(xx,sy(183),140,1);ctx.fillStyle='#54cfca';ctx.fillRect(xx,sy(183),30,2)}
// gates and their unlocking status
for(const g of gates){let x=sx(g.x),open=flags.terminals.filter(Boolean).length>=g.need;ctx.fillStyle=open?'#32b9a766':'#321e27cc';ctx.fillRect(x-9,sy(ground-134),18,134);ctx.strokeStyle=open?'#76f5cf':'#f27770';ctx.lineWidth=2;ctx.strokeRect(x-9,sy(ground-134),18,134);for(let yy=ground-124;yy<ground;yy+=19){ctx.fillStyle=open?'#77f1c7':'#ce625f';ctx.fillRect(x-5,sy(yy),10,3)}ctx.fillStyle='#bde4df';ctx.font='9px monospace';ctx.save();ctx.translate(x-16,sy(ground-143));ctx.rotate(-Math.PI/2);ctx.fillText(open?'ACCESS GRANTED':g.label,0,0);ctx.restore()}
// console props
for(const t of terminals){let x=sx(t.x),y=sy(ground-54),active=flags.terminals[t.n];ctx.fillStyle='#12272d';ctx.fillRect(x-15,y,30,54);ctx.fillStyle=active?'#51e4c3':'#34474b';ctx.fillRect(x-11,y+7,22,22);ctx.fillStyle=active?'#c3fff2':'#df7770';ctx.fillRect(x-7,y+11,14,4);ctx.fillStyle='#729ba0';ctx.fillRect(x-18,y+51,36,4);if(!active&&Math.abs(player.x+14-t.x)<86){ctx.fillStyle='#dbf9f1';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText(flags[['beam','armor','burst'][t.n]]?'[ E ] OVERRIDE':'SYSTEMS OFFLINE',x,y-9);ctx.textAlign='left'}}
// pulsing pickups
for(const p of pickups){if(p.got)continue;let x=sx(p.x),y=sy(p.y)+Math.sin(performance.now()/260+p.x)*5;ctx.save();ctx.shadowBlur=22;ctx.shadowColor=p.type==='beam'?'#65ffff':p.type==='armor'?'#ffd477':'#d197ff';ctx.fillStyle=ctx.shadowColor;ctx.beginPath();ctx.arc(x,y,11,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#e2ffff';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,15,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#062126';ctx.font='bold 11px monospace';ctx.textAlign='center';ctx.fillText(p.type==='beam'?'B':p.type==='armor'?'V':'ϟ',x,y+4);ctx.textAlign='left';ctx.restore()}
// enemies
for(const e of enemies){if(!e.alive)continue;let x=sx(e.x),y=sy(e.y);ctx.save();ctx.translate(x+e.w/2,y+e.h/2);ctx.fillStyle=e.type?'#c96a55':'#7b9b70';ctx.strokeStyle='#ffc178';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(0,0,e.w*.48,e.h*.42,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#10171b';ctx.fillRect(-8,-4,16,5);ctx.fillStyle='#ffcf73';ctx.fillRect(-6,-3,4,3);ctx.fillRect(3,-3,4,3);ctx.fillStyle='#718277';ctx.fillRect(-e.w/2,10,8,4);ctx.fillRect(e.w/2-8,10,8,4);ctx.restore()}
// boss and health
if(boss.alive){let x=sx(boss.x),y=sy(boss.y);ctx.save();ctx.shadowBlur=14;ctx.shadowColor='#e67452';ctx.fillStyle=boss.flash?'#fff2c4':'#793d46';ctx.strokeStyle='#ffb176';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+8,y+boss.h);ctx.lineTo(x+3,y+22);ctx.lineTo(x+20,y+3);ctx.lineTo(x+45,y+3);ctx.lineTo(x+boss.w-2,y+23);ctx.lineTo(x+boss.w-8,y+boss.h);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#fc5d64';ctx.fillRect(x+19,y+26,26,8);ctx.fillStyle='#f9d49a';ctx.fillRect(x+24,y+28,16,3);ctx.fillStyle='#333';ctx.fillRect(x,y-13,boss.w,5);ctx.fillStyle='#f47767';ctx.fillRect(x,y-13,boss.w*boss.hp/boss.max,5);ctx.restore()}
for(const b of bullets){ctx.save();ctx.shadowBlur=12;ctx.shadowColor='#6ffff4';ctx.fillStyle=b.charged?'#caffee':'#75e7ff';ctx.fillRect(sx(b.x)-5,sy(b.y)-2,b.charged?15:9,4);ctx.restore()}for(const b of enemyShots){ctx.fillStyle='#ff785f';ctx.shadowBlur=12;ctx.shadowColor='#ff5a4f';ctx.beginPath();ctx.arc(sx(b.x),sy(b.y),6,0,7);ctx.fill();ctx.shadowBlur=0}
// player silhouette with energy suit
if(!(player.invuln>0&&Math.floor(performance.now()/80)%2===0)){let x=sx(player.x),y=sy(player.y);ctx.save();ctx.translate(x+player.w/2,y);ctx.scale(player.face,1);ctx.shadowBlur=player.burst>0?24:7;ctx.shadowColor='#45e7db';ctx.fillStyle=player.burst>0?'#b4fff2':'#c06d43';ctx.beginPath();ctx.moveTo(-12,39);ctx.lineTo(-11,12);ctx.lineTo(-8,4);ctx.lineTo(1,0);ctx.lineTo(10,5);ctx.lineTo(12,17);ctx.lineTo(9,24);ctx.lineTo(13,40);ctx.lineTo(5,44);ctx.lineTo(2,30);ctx.lineTo(-4,30);ctx.lineTo(-7,45);ctx.closePath();ctx.fill();ctx.fillStyle='#e1b06c';ctx.beginPath();ctx.arc(1,9,10,Math.PI,0);ctx.fill();ctx.fillStyle='#61f3e7';ctx.fillRect(0,9,10,5);ctx.fillStyle='#174249';ctx.fillRect(-9,22,16,5);ctx.fillStyle='#ffbd68';ctx.fillRect(11,19,8,7);ctx.fillStyle='#eafdf7';ctx.fillRect(17,21,5,3);ctx.restore()}
for(const p of particles){ctx.globalAlpha=clamp(p.life*2,0,1);ctx.fillStyle=p.color;ctx.fillRect(sx(p.x),sy(p.y),p.r,p.r)}ctx.globalAlpha=1;
// ambient foreground vignette
const v=ctx.createRadialGradient(W/2,H/2,150,W/2,H/2,610);v.addColorStop(.5,'transparent');v.addColorStop(1,'#02080bcc');ctx.fillStyle=v;ctx.fillRect(0,0,W,H);
// progress strip and mini map
ctx.fillStyle='#071218dd';ctx.fillRect(W/2-172,16,344,22);ctx.strokeStyle='#4b797e';ctx.strokeRect(W/2-172,16,344,22);ctx.fillStyle='#73969b';ctx.font='9px monospace';ctx.fillText('BLACKSITE-09',W/2-161,30);ctx.fillStyle='#1f3a40';ctx.fillRect(W/2-72,24,226,4);ctx.fillStyle='#64e1d7';ctx.fillRect(W/2-72,24,226*player.x/worldW,4);ctx.fillStyle='#e7c17f';ctx.fillRect(W/2-72+226*player.x/worldW-2,21,4,10);
if(flash>0){ctx.fillStyle=`rgba(250,70,65,${flash*.35})`;ctx.fillRect(0,0,W,H)}
}
function loop(now){if(!running)return;let dt=(now-last)/1000;last=now;if(!paused)update(dt);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);draw();ctx.restore();requestAnimationFrame(loop)}
// User-friendly touch input and responsive crisp canvas.
canvas.addEventListener('pointerdown',()=>{if(!running)startGame()});
window.addEventListener('blur',()=>{keysDown.left=keysDown.right=keysDown.jump=keysDown.fire=false});
</script></body></html>

